import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { hasSlot } from "../../utils/slot";

interface Parent {
	name: string;
}

interface FlatItem {
	parents: Parent[];
	name: string;
	label?: string;
}

interface ItemWithChildren {
	id: string;
	children?: ItemWithChildren[];
}

function getIsAllChecked<T extends ItemWithChildren>(
	data: Array<T>,
	selection: Array<string>,
): boolean {
	if (!data) return false;
	return data.every((s) => {
		if (
			!Array.isArray(s.children) ||
			(Array.isArray(s.children) && s.children.length === 0)
		) {
			return selection.includes(s.id);
		}
		if (Array.isArray(s.children) && s.children.length)
			// preserve this for further use, return selection.includes(s.id) && getIsAllChecked(s.children, selection);
			return getIsAllChecked(s.children, selection);
	});
}

/**
 * get tags
 */
function handleTags(data, tags, selection, shouldRemove) {
	if (Array.isArray(data) && data.length) {
		data.forEach((d) => {
			const isDirectChildrenChecked =
				Array.isArray(d.children) &&
				d.children.every((c) => selection.includes(c.id));
			if (
				(isDirectChildrenChecked || selection.includes(d.id)) &&
				!shouldRemove
			) {
				const tag = { ...d };
				tag.handleTagRemove = handleTagRemove;
				tags.add(tag);
			}
			handleTags(d.children, tags, selection, isDirectChildrenChecked);
		});
	}
}
function getTags({ data, selection }) {
	const tags = new Set([]);
	handleTags(data, tags, selection, false);
	return Array.from(tags);
}

/**
 * handle remove tags
 */
function handleSelectionByTag({
	id,
	data,
	selectionSet,
	selection,
	shouldRemove,
}) {
	if (Array.isArray(data) && data.length) {
		data.forEach((d) => {
			if (shouldRemove || d.id === id) {
				selectionSet.delete(d.id);
			}
			if (d.children && d.id === id) {
				shouldRemove = true;
			}
			handleSelectionByTag({
				id,
				data: d.children,
				selectionSet,
				selection,
				shouldRemove,
			});
			if (d.id === id) {
				shouldRemove = false;
			}
		});
	}
}
function handleTagRemove({ id, data, selection }) {
	const selectionSet = new Set(selection);
	handleSelectionByTag({
		id,
		data,
		selectionSet,
		selection,
		shouldRemove: false,
	});
	return Array.from(selectionSet);
}

/**
 * flat search
 */
function flattenTreeWithParents<T>(
	tree: Array<T>,
	condition: (node: T & { children?: unknown[] }) => boolean = (node) =>
		!node.children,
) {
	const result: Array<T> = [];

	function traverse(
		node: T & { children?: T[] },
		parent: (T & { parents: object[] }) | undefined,
	) {
		if (!node) return;

		const _node = {
			...node,
			parents: [],
		};
		if (typeof parent === "object") {
			// @ts-ignore
			_node.parents = [...parent.parents, parent];
		}
		condition(_node) && result.push(_node);

		if (Array.isArray(node.children) && node.children.length > 0) {
			node.children.forEach((child: T) => traverse(child, _node));
		}
	}

	tree.forEach((node) => traverse(node, undefined));
	return result;
}

/**
 * @since 2.4.0
 * @status beta
 *
 * @slot - The cascader's content slot
 * @slot - The cascader's header slot
 * @slot - The cascader's footer slot
 *
 * @part base - The component's base wrapper.
 * @part header - The component's header wrapper.
 * @part body - The component's body wrapper.
 * @part footer - The component's footer wrapper.
 */

@Component({
	tag: "hbr-cascader",
	styleUrl: "cascader.scss",
	shadow: true,
})
export class Cascader {
	@State() defaultSlot = false;
	@State() headerSlot = false;
	@State() footerSlot = false;
	@Element() host: HTMLHbrCascaderElement;
	initialized = false;

	/**
	 * The data state is required.
	 */
	@Prop() data = [];
	/**
	 * The selection state is required.
	 */
	@Prop() selection = [];
	/**
	 * The open state is required.
	 */
	@Prop() open = [];
	/**
	 * For multiple selection.
	 */
	@Prop({ reflect: true }) multiple = false;

	/**
	 * Emit when selection change.
	 */
	@Event({ eventName: "hbr-selection" }) hbrSelection: EventEmitter;
	/**
	 * Emit when open change.
	 */
	@Event({ eventName: "hbr-open" }) hbrOpen: EventEmitter;
	/**
	 * Emit the tags' data when selection changes.
	 */
	@Event({ eventName: "hbr-tags" }) hbrTags: EventEmitter;
	/**
	 * Emit when data changes.
	 */
	@Event({ eventName: "hbr-data-change" }) hbrDataChange: EventEmitter;
	/**
	 * Emit when menu changes.
	 */
	@Event({ eventName: "hbr-menu" }) hbrMenu: EventEmitter;

	connectedCallback() {
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleA11yKB = this.handleA11yKB.bind(this);
		this.handleOpenChange = this.handleOpenChange.bind(this);
		this.handleTree = this.handleTree.bind(this);
		this.handleSelection = this.handleSelection.bind(this);
		this.handleSelectChildren = this.handleSelectChildren.bind(this);
		this.loopChildren = this.loopChildren.bind(this);
		this.handleOpenMenu = this.handleOpenMenu.bind(this);
		this.openMenu = this.openMenu.bind(this);
		this.closeMenu = this.closeMenu.bind(this);
		this.handleFlatData = this.handleFlatData.bind(this);
		this.handleResponsive = this.handleResponsive.bind(this);
	}

	disconnectedCallback() {
		window.removeEventListener("resize", this.handleResponsive);
	}

	private handleSlotChange() {
		this.headerSlot = hasSlot(this.host, "header");
		this.footerSlot = hasSlot(this.host, "footer");
		this.defaultSlot = hasSlot(this.host);
	}

	componentWillLoad() {
		this.handleSlotChange();
		this.handleDataChange(this.data);
	}

	componentDidLoad() {
		const tags = getTags({ data: this.data, selection: this.selection });
		this.hbrTags.emit({ tags });
		window.addEventListener("resize", this.handleResponsive);
	}

	@Watch("open")
	async handleResponsive() {
		const menus = Array.from(this.host?.querySelectorAll("hbr-menu"));
		const totalWidth = await menus.reduce(async (accPromise, menu) => {
			if (!menu.classList.contains("hydrated")) {
				await this.waitForHydrated(menu);
			}
			const acc = await accPromise;
			const rect = menu?.getBoundingClientRect();
			if (rect) {
				return acc + rect.width;
			}
			return acc;
		}, Promise.resolve(0));
		const isBiggerThanWindow = totalWidth + 24 > window.innerWidth;

		if (isBiggerThanWindow) {
			this.host.classList.add("hbr-css__cascader-responsive");
		} else {
			this.host.classList.remove("hbr-css__cascader-responsive");
		}
	}

	waitForHydrated = (element) => {
		return new Promise((resolve) => {
			if (element.classList.contains("hydrated")) {
				resolve(true);
			} else {
				const observer = new MutationObserver((mutations) => {
					mutations.forEach((mutation) => {
						if (
							mutation.type === "attributes" &&
							mutation.attributeName === "class" &&
							element.classList.contains("hydrated")
						) {
							observer.disconnect();
							resolve(true);
						}
					});
				});
				observer.observe(element, { attributes: true });
			}
		});
	};

	@Watch("data")
	handleDataChange(value) {
		const data = this.handleFlatData(value);
		const openMenus = [];
		this.handleTree({
			data: this.data,
			value: this.open[this.open.length - 1],
			openMenus,
			parent: this.data,
			open: [],
			close: false,
		});
		if (openMenus.length === 0) openMenus.push(this.data);
		this.hbrDataChange.emit({ ...data, menu: openMenus });
	}

	@Watch("selection")
	handleTags() {
		const tags = getTags({ data: this.data, selection: this.selection });
		this.hbrTags.emit({ tags });
	}

	@Method()
	openMenu(id) {
		return this.handleOpenMenu({ id });
	}

	handleFlatData(data) {
		const flat: FlatItem[] = flattenTreeWithParents(data);
		const format = flat.map((item) => {
			const prefix = item.parents.reduce((pre, cur) => {
				return pre ? `${pre} / ${cur.name}` : cur.name;
			}, "");
			const label = prefix ? `${prefix} / ${item.name}` : item.name;
			item.label = label;
			item.parents = undefined;
			return item;
		});
		return {
			flat,
			format,
		};
	}

	handleOpenMenu({ id, close = false }) {
		const openMenus = [];
		const open = [];
		this.handleTree({
			data: this.data,
			value: id,
			openMenus,
			parent: this.data,
			open,
			close,
		});
		open.unshift("");
		this.hbrOpen.emit({ open });
		this.hbrMenu.emit({ data: openMenus });
		return new Promise(() => true);
	}

	@Method()
	closeMenu(id) {
		return this.handleOpenMenu({ id, close: true });
	}

	private handleTree({ data, value, openMenus, parent, open, close = false }) {
		for (const d of data) {
			if (d.id === value) {
				if (d.children?.length) {
					if (!close) {
						open.unshift(d.id);
						openMenus.push(d.children);
					}
					d.children.forEach((c) => {
						c.parentid = d.id;
					});
				}
				parent && openMenus.unshift(parent);
				return openMenus;
			}
			if (d.children) {
				const selected = this.handleTree({
					data: d.children,
					value,
					openMenus,
					parent: d.children,
					open,
					close,
				});
				if (selected) {
					if (!selected.includes(parent)) {
						open.unshift(d.id);
						selected.unshift(parent);
					}
					return selected;
				}
			}
		}
	}

	private handleOpenChange(e) {
		if (e.detail.event.srcElement.tagName === "HBR-CHECKBOX") {
			return;
		}
		const openMenus = [];
		const open = [];
		this.handleTree({
			data: this.data,
			value: e.detail.item.value,
			openMenus,
			parent: this.data,
			open,
		});
		open.unshift("");
		this.hbrOpen.emit({ open, item: e.detail.item });
		this.hbrMenu.emit({ data: openMenus });
		if (!this.multiple && e.detail.item.leaf) {
			this.hbrSelection.emit({ item: e.detail.item });
		}
	}

	private getItemById(data, id) {
		for (const d of data) {
			if (d.id === id) return d;
			if (d.children) {
				const item = this.getItemById(d.children, id);
				if (item) return item;
			}
		}
	}

	private handleSelectChildren(data, selection, selected) {
		if (Array.isArray(data) && data.length) {
			data.forEach((d) => {
				if (selected) {
					selection.add(d.id);
				} else {
					selection.delete(d.id);
				}
				this.handleSelectChildren(d.children, selection, selected);
			});
		}
	}

	private loopChildren<T extends { children }>(
		children: T[],
		fn: (c: T) => boolean,
	): void {
		for (const c of children) {
			if (fn(c)) break;
			if (Array.isArray(c.children)) this.loopChildren(c.children, fn);
		}
	}

	private handleSelectParent(data, selection) {
		if (data && Array.isArray(data) && data.length) {
			return data.every((node) => {
				const isAllCheck = this.handleSelectParent(node.children, selection);
				if (isAllCheck) {
					selection.add(node.id);
				}
				return selection.has(node.id);
			});
		}
	}

	private handleUnselectParent(data, selection) {
		data.forEach((node) => {
			if (node && Array.isArray(node.children) && node.children.length) {
				const isAllChecked = getIsAllChecked(
					node.children,
					Array.from(selection),
				);
				if (isAllChecked) {
					selection.add(node.id);
				} else {
					selection.delete(node.id);
				}
				this.handleUnselectParent(node.children, selection);
			}
		});
	}

	private handleSelection(e) {
		const id = e.target.closest("hbr-menu-item").dataset.id;
		const selection = new Set(this.selection);
		const item = this.getItemById(this.data, id);
		if (e.target.checked) {
			selection.add(id);
		} else {
			selection.delete(id);
		}
		this.handleSelectChildren(item.children, selection, e.target.checked);
		this.handleSelectParent(this.data, selection);
		this.handleUnselectParent(this.data, selection);
		this.hbrSelection.emit({ selection: Array.from(selection) });
	}

	handleA11yKB(e) {
		const item = e.target.closest("hbr-menu-item");
		if (!item) return;
		if (e.key === "ArrowRight") {
			const id = item.dataset.id;
			this.openMenu(id);
			setTimeout(() => {
				const menus = Array.from(this.host.querySelectorAll("hbr-menu"));
				const idx = menus.findIndex((menu) => menu.contains(item));
				const index = idx + 1;
				if (index >= menus.length) return;
				const next = menus[index];
				next?.getMenuItems().then((items) => {
					if (items.length) {
						items[0]?.setFocus();
					}
				});
			});
		} else if (e.key === "ArrowLeft") {
			setTimeout(() => {
				const parentid = item.dataset.parentid;
				if (parentid) {
					this.closeMenu(parentid);
					const parentItem = this.host.querySelector(
						`hbr-menu-item[data-id="${parentid}"]`,
					) as HTMLHbrMenuItemElement;
					if (parentItem) {
						parentItem.setFocus();
					}
				}
			});
		} else if ([" ", "Enter"].includes(e.key)) {
			const checkbox = item.querySelector("hbr-checkbox");
			item.checked = !item.checked;
			checkbox?.setCheck();
		}
	}

	render() {
		return (
			<Host data-header={this.headerSlot} data-footer={this.footerSlot}>
				<div
					part="base"
					class={{
						cascader: true,
						"cascading-has-menu":
							this.defaultSlot || this.headerSlot || this.footerSlot,
					}}
					onhbr-select={this.handleOpenChange}
					onhbr-click={this.handleSelection}
					onKeyDown={this.handleA11yKB}
				>
					<span
						part="header"
						class={{
							"cascader-header": true,
							"cascader-has-header": this.headerSlot,
						}}
					>
						<slot onSlotchange={this.handleSlotChange} name="header" />
					</span>
					<span class="cascader-body" part="body">
						<slot onSlotchange={this.handleSlotChange} />
					</span>
					<span
						part="footer"
						class={{
							"cascader-footer": true,
							"cascader-has-footer": this.footerSlot,
						}}
					>
						<slot onSlotchange={this.handleSlotChange} name="footer" />
					</span>
				</div>
			</Host>
		);
	}
}
